from z3 import *

# Social Golfers Problem: 35 golfers, 7 groups of 5, 5 weeks
# Each entry schedule[w][p] = group (0-6) for golfer p in week w

num_golfers = 35
num_groups = 7
group_size = 5
num_weeks = 5

# Create variables: schedule[w][p] = group assignment
schedule = [[Int(f's_{w}_{p}') for p in range(num_golfers)] for w in range(num_weeks)]

solver = Optimize()

# Constraint 1: Each golfer is assigned to a valid group (0-6)
for w in range(num_weeks):
    for p in range(num_golfers):
        solver.add(schedule[w][p] >= 0, schedule[w][p] <= 6)

# Constraint 2: Each week, each group has exactly 5 golfers
for w in range(num_weeks):
    for g in range(num_groups):
        solver.add(Sum([If(schedule[w][p] == g, 1, 0) for p in range(num_golfers)]) == group_size)

# Constraint 3: No pair of golfers plays together more than once
for p1 in range(num_golfers):
    for p2 in range(p1 + 1, num_golfers):
        # Count how many weeks they're in the same group
        same_group_count = Sum([If(schedule[w][p1] == schedule[w][p2], 1, 0) for w in range(num_weeks)])
        solver.add(same_group_count <= 1)

print("Solving...")
result = solver.check()
print(f"Result: {result}")

if result == sat:
    m = solver.model()
    solution = []
    for w in range(num_weeks):
        for p in range(num_golfers):
            solution.append(m[schedule[w][p]].as_long())

    # Verify the solution
    print("Verifying solution...")
    valid = True

    # Check group sizes
    for w in range(num_weeks):
        for g in range(num_groups):
            count = sum(1 for p in range(num_golfers) if solution[w*35 + p] == g)
            if count != 5:
                print(f"Week {w}, Group {g}: {count} golfers (should be 5)")
                valid = False

    # Check pair constraint
    pair_count = {}
    for w in range(num_weeks):
        for g in range(num_groups):
            golfers_in_group = [p for p in range(num_golfers) if solution[w*35 + p] == g]
            for i in range(len(golfers_in_group)):
                for j in range(i+1, len(golfers_in_group)):
                    pair = (min(golfers_in_group[i], golfers_in_group[j]), 
                           max(golfers_in_group[i], golfers_in_group[j]))
                    pair_count[pair] = pair_count.get(pair, 0) + 1

    violations = [pair for pair, count in pair_count.items() if count > 1]
    if violations:
        print(f"Found {len(violations)} pair violations")
        valid = False

    if valid:
        print("Solution is valid!")
        print(solution)
    else:
        print("Solution is invalid")
else:
    print("UNSATISFIABLE")

