import random
from itertools import combinations

num_golfers = 35
num_groups = 7
group_size = 5
num_weeks = 5

# For each week, we need to partition 35 golfers into 7 groups of 5
# Constraint: no pair appears together more than once

# Track which pairs have been grouped together
pair_used = set()

def get_pairs(group):
    """Get all pairs from a group"""
    return set(combinations(sorted(group), 2))

def is_valid_group(group, week):
    """Check if adding this group would violate pair constraints"""
    pairs = get_pairs(group)
    return not any(p in pair_used for p in pairs)

def add_group(group):
    """Add a group's pairs to the used set"""
    pairs = get_pairs(group)
    for p in pairs:
        pair_used.add(p)

def remove_group(group):
    """Remove a group's pairs from the used set"""
    pairs = get_pairs(group)
    for p in pairs:
        pair_used.discard(p)

def solve():
    # Initialize schedule
    schedule = [[-1] * num_golfers for _ in range(num_weeks)]

    # Fix week 0: golfers 0-4 in group 0, 5-9 in group 1, etc.
    for g in range(num_groups):
        for p in range(g * group_size, (g + 1) * group_size):
            schedule[0][p] = g
            for p2 in range(g * group_size, (g + 1) * group_size):
                if p2 > p:
                    pair_used.add((p, p2))

    # Now solve for weeks 1-4
    def backtrack(week, golfer, groups):
        """
        week: current week (1-4)
        golfer: current golfer to assign
        groups: list of 7 groups, each is a list of golfers assigned so far
        """
        if week >= num_weeks:
            return True

        if golfer >= num_golfers:
            # Move to next week
            # Add all pairs from this week to pair_used
            for g in range(num_groups):
                for p1, p2 in combinations(sorted(groups[g]), 2):
                    pair_used.add((p1, p2))

            # Reset for next week
            new_groups = [[] for _ in range(num_groups)]
            result = backtrack(week + 1, 0, new_groups)

            # Remove pairs
            for g in range(num_groups):
                for p1, p2 in combinations(sorted(groups[g]), 2):
                    pair_used.discard((p1, p2))

            return result

        # Try assigning golfer to each group
        for g in range(num_groups):
            if len(groups[g]) >= group_size:
                continue

            # Check if this assignment is valid
            valid = True
            for existing in groups[g]:
                pair = (min(existing, golfer), max(existing, golfer))
                if pair in pair_used:
                    valid = False
                    break

            if not valid:
                continue

            # Assign
            groups[g].append(golfer)
            schedule[week][golfer] = g

            if backtrack(week, golfer + 1, groups):
                return True

            # Backtrack
            groups[g].pop()
            schedule[week][golfer] = -1

        return False

    # Initialize groups for week 1
    groups = [[] for _ in range(num_groups)]

    if backtrack(1, 0, groups):
        # Convert to flat list
        solution = []
        for w in range(num_weeks):
            for p in range(num_golfers):
                solution.append(schedule[w][p])
        return solution
    return None

print("Trying backtracking...")
solution = solve()
if solution:
    print("Found solution!")
    print(solution)
else:
    print("No solution found with basic backtracking")

